1216	  private readonly STATUS_ABERTOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'];
1217	  private readonly COMANDA_STATUS_ABERTOS = ['aberta', 'fechada_garcom'];
1218	
1219	  // Venda finalizada = entregue (delivery) ou paga (comanda do salão) — sem isso o
1220	  // resumo/KPI do dashboard ignorava toda venda do salão (comanda nunca vira 'delivered').
1221	  private readonly STATUS_VENDA_FINALIZADA = ['delivered', 'paga'];
1222	
1223	  // Comanda do salão pode ter N pagamentos com formas diferentes (parcial pelo garçom +
1224	  // resto pelo caixa) — orders.payment_method só guarda a última forma usada no
1225	  // fechamento, então pra decompor certo o "por forma de pagamento" precisa ir direto
1226	  // no ledger de comanda_pagamentos. Delivery continua com pagamento único (sem mudança).
1227	  private async buscarPagamentosPorComanda(pedidos: any[]): Promise<Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>> {
1228	    const idsComanda = pedidos.filter((p: any) => p.canal === 'presencial').map((p: any) => p.id);
1229	    const mapa = new Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>();
1230	    if (!idsComanda.length) return mapa;
1231	
1232	    const { data } = await this.supabase.client
1233	      .from('comanda_pagamentos')
1234	      .select('order_id, valor, valor_recebido, forma_pagamento, origem, troco, criado_em, taxa_cartao_valor')
1235	      .in('order_id', idsComanda);
1236	
1237	    for (const p of (data ?? []) as any[]) {
1238	      if (!mapa.has(p.order_id)) mapa.set(p.order_id, []);
1239	      mapa.get(p.order_id)!.push({ order_id: p.order_id, valor: p.valor, valor_recebido: p.valor_recebido ?? null, forma_pagamento: p.forma_pagamento, origem: p.origem, troco: p.troco ?? 0, criado_em: p.criado_em, taxa_cartao_valor: p.taxa_cartao_valor ?? 0 });
1240	    }
1241	    return mapa;
1242	  }
