1244	  private calcularResumo(
1245	    pedidos: any[],
1246	    saidas: any[],
1247	    valor_inicial: number,
1248	    entradas: any[] = [],
1249	    pagamentosPorComanda?: Map<number, { valor: number; valor_recebido?: number | null; forma_pagamento: string; taxa_cartao_valor?: number }[]>,
1250	  ) {
1251	    const entregues = pedidos.filter((p) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
1252	    const total_saidas = saidas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1253	    const total_entradas = entradas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1254	
1255	    // orders.total (comanda do salão) guarda só subtotal-desconto+acréscimo — a taxa de
1256	    // cartão cobrada do cliente fica em comanda_pagamentos.taxa_cartao_valor. Entra num
1257	    // bucket "taxa_cartao" à parte (não somado dentro de Cartão Crédito/Débito) pra
1258	    // aparecer explícito na conferência de fechamento, sem esconder dentro da forma.
1259	    let total_vendas = 0;
1260	    const por_pagamento: Record<string, number> = {};
1261	    // Taxa por forma (não some no bucket único "taxa_cartao") — pra tela de fechamento
1262	    // poder mostrar "Débito R$161,70 + taxa R$11,32 = R$173,02" em vez de um total
1263	    // de taxa solto, sem saber se veio do débito ou do crédito.
1264	    const taxa_por_forma: Record<string, number> = {};
1265	    // Dinheiro que o cliente entregou de fato (valor_recebido) — só pra exibição na
1266	    // conferência de fechamento. O que entra/sai fisicamente do caixa já é lançado como
1267	    // entrada/saída no ledger (ver registrarEntradaCaixa/registrarSaidaCaixa em
1268	    // salao.service.ts), então especie_calculada usa entradas_especie/saidas_especie,
1269	    // não esse valor — contar os dois juntos duplicaria a entrada em espécie.
1270	    let cash_recebido = 0;
1271	    for (const p of entregues) {
1272	      const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComanda?.get(p.id) : undefined;
1273	      if (pagamentosComanda?.length) {
1274	        for (const pag of pagamentosComanda) {
1275	          const m = pag.forma_pagamento ?? 'outro';
1276	          const taxa = pag.taxa_cartao_valor ?? 0;
1277	          por_pagamento[m] = (por_pagamento[m] ?? 0) + (pag.valor ?? 0);
1278	          if (taxa > 0) {
1279	            por_pagamento['taxa_cartao'] = (por_pagamento['taxa_cartao'] ?? 0) + taxa;
1280	            taxa_por_forma[m] = (taxa_por_forma[m] ?? 0) + taxa;
1281	          }
1282	          total_vendas += (pag.valor ?? 0) + taxa;
1283	          if (m === 'cash') cash_recebido += pag.valor_recebido ?? pag.valor ?? 0;
1284	        }
1285	      } else {
1286	        const m = p.payment_method ?? 'outro';
1287	        por_pagamento[m] = (por_pagamento[m] ?? 0) + (p.total ?? 0);
1288	        total_vendas += p.total ?? 0;
1289	        if (m === 'cash') cash_recebido += p.total ?? 0;
1290	      }
1291	    }
1292	
1293	    const saidas_especie = saidas
1294	      .filter((s: any) => !s.meio || s.meio === 'dinheiro')
1295	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1296	    const entradas_especie = entradas
1297	      .filter((e: any) => !e.meio || e.meio === 'dinheiro')
1298	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1299	    const especie_calculada = valor_inicial + entradas_especie - saidas_especie;
1300	
1301	    // Movimentos em Pix fora da venda em si — hoje só o troco devolvido via Pix (ver
1302	    // troco_via_pix em comanda_pagamentos/salao-pdv.service.ts), que sai do Pix do
1303	    // estabelecimento sem passar pela espécie física. Não tem "fundo inicial" em Pix —
1304	    // pix_calculado é só o líquido desses ajustes (normalmente negativo).
1305	    const saidas_pix = saidas
1306	      .filter((s: any) => s.meio === 'pix')
1307	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1308	    const entradas_pix = entradas
1309	      .filter((e: any) => e.meio === 'pix')
1310	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1311	    const pix_calculado = entradas_pix - saidas_pix;
1312	
1313	    // saldo (contábil) já conta a venda em dinheiro via total_vendas — as entradas/saídas
1314	    // automáticas de venda_dinheiro/troco (ver registrarEntradaCaixa/registrarSaidaCaixa em
1315	    // salao.service.ts) representam a MESMA venda no ledger físico do caixa. Somar
1316	    // total_entradas/total_saidas crus aqui contaria essa venda duas vezes. Filtra fora só
1317	    // pra esse cálculo — total_entradas/total_saidas retornados continuam com tudo, pro
1318	    // ledger (KPIs "Adições"/"Sangrias") mostrar os lançamentos automáticos normalmente.
1319	    // estorno_troco compensa o troco original (já fora de saidas_saldo) quando um
1320	    // pagamento com troco é corrigido/removido — mesma lógica do estorno_pagamento.
1321	    const entradas_saldo = entradas
1322	      .filter((e: any) => e.tipo !== 'venda_dinheiro' && e.tipo !== 'estorno_troco')
1323	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1324	    // estorno_pagamento compensa uma venda_dinheiro que também já ficou de fora daqui
1325	    // (pagamento corrigido/removido) — mesma lógica do troco, senão penaliza o saldo
1326	    // líquido por uma venda que nem conta mais em total_vendas.
1327	    const saidas_saldo = saidas
1328	      .filter((s: any) => s.tipo !== 'troco' && s.tipo !== 'estorno_pagamento')
1329	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1330	
1331	    return {
1332	      total_pedidos: pedidos.length,
1333	      entregues: entregues.length,
1334	      em_andamento: pedidos.filter((p: any) => this.STATUS_ABERTOS.includes(p.status) || this.COMANDA_STATUS_ABERTOS.includes(p.status)).length,
1335	      cancelados: pedidos.filter((p: any) => p.status === 'canceled').length,
1336	      total_vendas,
1337	      total_saidas,
1338	      total_entradas,
1339	      saldo: valor_inicial + total_vendas + entradas_saldo - saidas_saldo,
1340	      por_pagamento,
1341	      taxa_por_forma,
1342	      especie_calculada,
1343	      saidas_especie,
1344	      entradas_especie,
1345	      pix_calculado,
1346	      saidas_pix,
1347	      entradas_pix,
1348	      cash_recebido,
1349	    };
1350	  }
