1358	    const status_restaurante: boolean = (restaurantData?.aparencia?.aberto) === true;
1359	    const saldo_caixa: number = restaurantData?.saldo_caixa ?? 0;
1360	
1361	    // Saldo de caixas fechados que não passaram pelo fluxo de destinação
1362	    // (criados antes da feature — o dinheiro físico ainda existe e deve ser contabilizado)
1363	    const { data: caixasSemDestinacao } = await this.supabase.client
1364	      .from('caixas')
