1368	      .is('destinacao_fechamento', null);
1369	
1370	    const saldo_fechados_pendente: number = (caixasSemDestinacao ?? []).reduce((sum: number, c: any) => {
1371	      return sum + (c.resumo?.saldo ?? 0);
1372	    }, 0);
1373	
1374	    const { data: caixa } = await this.supabase.client
1375	      .from('caixas')
1376	      .select('*')
1377	      .eq('restaurant_id', restaurantId)
1378	      .eq('status', 'aberto')
