1397	    const pagamentosPorComanda = await this.buscarPagamentosPorComanda(pedidos);
1398	    const resumo = this.calcularResumo(pedidos, saidas, caixa.valor_inicial, entradas, pagamentosPorComanda);
1399	
1400	    return {
1401	      status_restaurante,
