1417	  async abrirCaixa(restaurantId: number, body: { nome_operador: string; valor_inicial?: number }) {
1418	    if (!body.nome_operador?.trim()) throw new BadRequestException('Nome do operador é obrigatório');
1419	
1420	    const { data: existente } = await this.supabase.client
1421	      .from('caixas').select('id, status').eq('restaurant_id', restaurantId)
1422	      .in('status', ['aberto', 'expirado']).maybeSingle();
1423	
1424	    if (existente?.status === 'aberto') throw new ConflictException('Já existe um caixa aberto');
1425	    if (existente?.status === 'expirado') throw new ConflictException('Existe um caixa expirado. Feche-o antes de abrir outro');
1426	
1427	    // Usar saldo_caixa como valor_inicial padrão se não informado
1428	    const { data: restaurant } = await this.supabase.client
1429	      .from('restaurants').select('saldo_caixa').eq('id', restaurantId).maybeSingle();
1430	    const saldoCaixaAtual = restaurant?.saldo_caixa ?? 0;
1431	    const valorInicial = body.valor_inicial !== undefined ? body.valor_inicial : saldoCaixaAtual;
1432	
1433	    const { data: novo, error } = await this.supabase.client
1434	      .from('caixas')
1435	      .insert({ restaurant_id: restaurantId, nome_operador: body.nome_operador.trim(), valor_inicial: valorInicial })
1436	      .select('*')
1437	      .single();
1438	
1439	    if (error) throw error;
1440	
1441	    // Zerar saldo_caixa — o valor agora está dentro do caixa aberto
1442	    await this.supabase.client.from('restaurants')
1443	      .update({ saldo_caixa: 0 }).eq('id', restaurantId);
1444	
1445	    return this.getCaixa(restaurantId);
1446	  }
