1448	  async fecharCaixa(restaurantId: number, body?: { dinheiro_contado?: number; permitir_pendencias?: boolean }) {
1449	    const { data: caixa } = await this.supabase.client
1450	      .from('caixas').select('*').eq('restaurant_id', restaurantId)
1451	      .in('status', ['aberto', 'expirado']).maybeSingle();
1452	
1453	    if (!caixa) throw new NotFoundException('Nenhum caixa aberto');
1454	
1455	    const { data: pedidosAbertos } = await this.supabase.client
1456	      .from('orders').select('id, status, total')
1457	      .eq('caixa_id', caixa.id)
1458	      .in('status', this.STATUS_ABERTOS);
1459	
1460	    const { data: comandasAbertas } = await this.supabase.client
1461	      .from('orders')
1462	      .select('id, status, mesa_id, mesas(numero, nome)')
1463	      .eq('caixa_id', caixa.id)
1464	      .eq('canal', 'presencial')
1465	      .in('status', this.COMANDA_STATUS_ABERTOS);
1466	
1467	    const { data: mesasAbertas } = await this.supabase.client
1468	      .from('mesas')
1469	      .select('id, numero, nome, status')
1470	      .eq('restaurant_id', restaurantId)
1471	      .neq('status', 'livre');
1472	
1473	    const temPendencias = (pedidosAbertos ?? []).length > 0 || (comandasAbertas ?? []).length > 0 || (mesasAbertas ?? []).length > 0;
1474	
1475	    if (temPendencias && !body?.permitir_pendencias) {
1476	      throw new ConflictException({
1477	        message: 'Existem pendências em aberto: feche os pedidos, comandas e mesas antes de fechar o caixa',
1478	        pedidos_abertos: pedidosAbertos?.length ?? 0,
1479	        pedidos: pedidosAbertos ?? [],
1480	        comandas_abertas: comandasAbertas?.length ?? 0,
1481	        comandas: comandasAbertas ?? [],
1482	        mesas_abertas: mesasAbertas?.length ?? 0,
1483	        mesas: mesasAbertas ?? [],
1484	      });
1485	    }
1486	
1487	    // Mesa não pode ficar travada esperando o caixa reabrir — libera pro próximo
1488	    // cliente e a pendência (se houver comanda em aberto) segue como fiado,
1489	    // cobrada no caixa aberto quando o pagamento acontecer.
1490	    if ((mesasAbertas ?? []).length > 0) {
1491	      await this.supabase.client
1492	        .from('mesas')
1493	        .update({ status: 'livre' })
1494	        .in('id', (mesasAbertas ?? []).map((m) => m.id));
1495	    }
1496	
1497	    const { data: todosPedidos } = await this.supabase.client
1498	      .from('orders').select('id, total, status, payment_method, canal, created_at')
1499	      .or(`caixa_id.eq.${caixa.id},and(caixa_id.is.null,created_at.gte.${caixa.aberto_em})`);
1500	
1501	    const saidas = (caixa.saidas ?? []) as any[];
1502	    const entradas = (caixa.entradas ?? []) as any[];
1503	    const pagamentosPorComanda = await this.buscarPagamentosPorComanda(todosPedidos ?? []);
1504	    const resumo = this.calcularResumo(todosPedidos ?? [], saidas, caixa.valor_inicial, entradas, pagamentosPorComanda);
1505	    const fechado_em = new Date().toISOString();
1506	
1507	    // Conferência: operador informa quanto contou; sistema compara com espécie calculada
1508	    const dinheiro_contado = body?.dinheiro_contado ?? (resumo.especie_calculada ?? 0);
1509	    const diferenca = dinheiro_contado - (resumo.especie_calculada ?? 0);
1510	    const destinacao_fechamento = {
1511	      dinheiro_contado,
1512	      especie_calculada: resumo.especie_calculada,
1513	      diferenca,
1514	      por_pagamento: resumo.por_pagamento,
1515	      conferencia_aprovada: false,
1516	    };
1517	
1518	    await this.supabase.client.from('caixas')
1519	      .update({
1520	        status: 'fechado', fechado_em, resumo, destinacao_fechamento,
1521	        fechado_com_pendencias: temPendencias,
1522	        pendencias_fechamento: temPendencias
1523	          ? { pedidos: pedidosAbertos ?? [], comandas: comandasAbertas ?? [], mesas: mesasAbertas ?? [] }
1524	          : null,
1525	      })
1526	      .eq('id', caixa.id);
1527	
1528	    // Sem caixa aberto não há como aceitar pedidos/comandas — fecha o restaurante junto
1529	    await this.updateAparencia(restaurantId, { aberto: false });
1530	
1531	    // saldo_caixa = dinheiro contado (o que vai pro cofre para o próximo caixa)
1532	    await this.supabase.client.from('restaurants')
1533	      .update({ saldo_caixa: Math.max(0, dinheiro_contado) }).eq('id', restaurantId);
1534	
1535	    return {
1536	      fechamento: {
1537	        id: caixa.id, aberto_em: caixa.aberto_em, fechado_em, nome_operador: caixa.nome_operador,
1538	        valor_inicial: caixa.valor_inicial, saidas, resumo, destinacao_fechamento,
1539	        fechado_com_pendencias: temPendencias,
1540	      },
1541	    };
1542	  }
