1544	  async aprovarConferencia(restaurantId: number, caixaId: number) {
1545	    const { data: caixa } = await this.supabase.client
1546	      .from('caixas').select('id, destinacao_fechamento')
1547	      .eq('id', caixaId).eq('restaurant_id', restaurantId).maybeSingle();
1548	    if (!caixa) throw new NotFoundException('Caixa não encontrado');
1549	    const dest = { ...(caixa.destinacao_fechamento ?? {}), conferencia_aprovada: true, aprovado_em: new Date().toISOString() };
1550	    const { error } = await this.supabase.client.from('caixas').update({ destinacao_fechamento: dest }).eq('id', caixaId);
1551	    if (error) throw error;
1552	    return { aprovado: true };
1553	  }
