1555	  async fecharComTransferencia(restaurantId: number, body: { nome_operador: string; valor_inicial?: number }) {
1556	    if (!body.nome_operador?.trim()) throw new BadRequestException('Nome do operador do novo caixa é obrigatório');
1557	
1558	    const { data: caixa } = await this.supabase.client
1559	      .from('caixas').select('*').eq('restaurant_id', restaurantId)
1560	      .in('status', ['aberto', 'expirado']).maybeSingle();
1561	
1562	    if (!caixa) throw new NotFoundException('Nenhum caixa aberto para fechar');
1563	
1564	    // Fechar caixa atual (com resumo)
1565	    const { data: todosPedidos } = await this.supabase.client
1566	      .from('orders').select('id, total, status, payment_method, canal, created_at')
1567	      .or(`caixa_id.eq.${caixa.id},and(caixa_id.is.null,created_at.gte.${caixa.aberto_em})`);
