import { supabase } from '../lib/supabase';
import { apiPath } from '../lib/apiUrl';

const API = apiPath('/api/restaurante');

async function apiFetch(path, options = {}) {
  const sessionResult = await supabase.auth.getSession().catch(() => ({ data: {} }));
  const token = sessionResult?.data?.session?.access_token;

  if (!token) throw new Error('Sessão expirada. Faça login novamente.');

  const res = await fetch(`${API}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      ...options.headers,
    },
  });

  const contentType = res.headers.get('content-type') ?? '';
  const isJson = contentType.includes('application/json');

  if (!res.ok) {
    const err = isJson ? await res.json().catch(() => ({})) : {};
    const error = new Error(err?.message ?? `HTTP ${res.status}`);
    error.data = err;
    throw error;
  }

  if (!isJson) throw new Error('Resposta inválida. Verifique se o backend está rodando.');

  return res.json();
}

export const registrarRestauranteInicial = (data) =>
  apiFetch('/registrar-inicial', { method: 'POST', body: JSON.stringify(data) });

export const finalizarCadastroRestaurante = (data) =>
  apiFetch('/finalizar', { method: 'POST', body: JSON.stringify(data) });

export const verificarDisponibilidadeCadastro = (data) =>
  apiFetch('/verificar-disponibilidade', { method: 'POST', body: JSON.stringify(data) });

export const getMinhaEmpresa = () => apiFetch('/minha-empresa');

export const getMeusPedidos = (params = {}) => {
  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v)).toString();
  return apiFetch(`/pedidos${qs ? `?${qs}` : ''}`);
};

export const atualizarStatusPedido = (id, status) =>
  apiFetch(`/pedidos/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) });

export const entregarPedidoProprio = (id) =>
  apiFetch(`/pedidos/${id}/entregar-proprio`, { method: 'PATCH' });

export const listarEntregas = () => apiFetch('/entregas');

export const getMeusProdutos = () => apiFetch('/produtos');

async fecharCaixa(restaurantId: number, body?: { dinheiro_contado?: number; permitir_pendencias?: boolean }) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('*').eq('restaurant_id', restaurantId)
    .in('status', ['aberto', 'expirado']).maybeSingle();

  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  const { data: pedidosAbertos } = await this.supabase.client
    .from('orders').select('id, status, total')
    .eq('caixa_id', caixa.id)
    .in('status', this.STATUS_ABERTOS);

  const { data: comandasAbertas } = await this.supabase.client
    .from('orders')
    .select('id, status, mesa_id, mesas(numero, nome)')
    .eq('caixa_id', caixa.id)
    .eq('canal', 'presencial')
    .in('status', this.COMANDA_STATUS_ABERTOS);

  const { data: mesasAbertas } = await this.supabase.client
    .from('mesas')
    .select('id, numero, nome, status')
    .eq('restaurant_id', restaurantId)
    .neq('status', 'livre');

  const temPendencias = (pedidosAbertos ?? []).length > 0 || (comandasAbertas ?? []).length > 0 || (mesasAbertas ?? []).length > 0;

  if (temPendencias && !body?.permitir_pendencias) {
    throw new ConflictException({
      message: 'Existem pendências em aberto: feche os pedidos, comandas e mesas antes de fechar o caixa',
      pedidos_abertos: pedidosAbertos?.length ?? 0,
      pedidos: pedidosAbertos ?? [],
      comandas_abertas: comandasAbertas?.length ?? 0,
      comandas: comandasAbertas ?? [],
      mesas_abertas: mesasAbertas?.length ?? 0,
      mesas: mesasAbertas ?? [],
    });
  }

  // Mesa não pode ficar travada esperando o caixa reabrir — libera pro próximo

