1	import React, { useState } from 'react';
2	
3	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
4	const fmtDate = (d) => d ? new Date(d).toLocaleString('pt-BR') : '-';
5	
6	const PL = { cash: 'Dinheiro', pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', taxa_cartao: '+ Taxa cartão' };
7	
8	const Row = ({ label, value, bold, accent, muted }) => (
9	  <div className={`flex justify-between text-sm py-1.5 border-b border-[#F4F4F5] dark:border-[#3F3F46] last:border-0 ${bold ? 'font-bold' : ''}`}>
10	    <span className={muted ? 'text-[#A1A1AA]' : 'text-[#71717A] dark:text-[#A1A1AA]'}>{label}</span>
11	    <span className={accent ? 'text-[#FF441F] font-bold' : muted ? 'text-[#A1A1AA]' : 'text-[#18181B] dark:text-[#F4F4F5]'}>{value}</span>
12	  </div>
13	);
14	
15	// ── Tela 0: pedidos/itens ainda em preparo/produção ───────────────────────────
16	const ITEM_STATUS_LABEL = { enviado: 'Aguardando', preparando: 'Em preparo' };
17	
18	const labelComanda = (order) => {
19	  if (order?.mesas) return `Mesa ${order.mesas.numero}${order.mesas.nome ? ` - ${order.mesas.nome}` : ''}`;
20	  if (order?.numero_comanda) return `Comanda #${order.numero_comanda}`;
21	  if (order?.cliente_mesa_nome) return order.cliente_mesa_nome;
22	  return 'Comanda';
23	};
24	
25	const PreparoEmAndamentoView = ({ pedidosEmPreparo, itensEmPreparo, onMarcarProntos, marcando, onContinuar, onCancelar }) => {
26	  const [pedidosSel, setPedidosSel] = useState(new Set());
27	  const [itensSel, setItensSel] = useState(new Set());
28	
29	  const totalItens = pedidosEmPreparo.length + itensEmPreparo.length;
30	  const totalSel = pedidosSel.size + itensSel.size;
31	
32	  const toggle = (setFn, id) => setFn((prev) => {
33	    const next = new Set(prev);
34	    next.has(id) ? next.delete(id) : next.add(id);
35	    return next;
36	  });
37	
38	  const selecionarTodos = () => {
39	    setPedidosSel(new Set(pedidosEmPreparo.map((p) => p.id)));
40	    setItensSel(new Set(itensEmPreparo.map((i) => i.id)));
41	  };
42	  const selecionarNenhum = () => { setPedidosSel(new Set()); setItensSel(new Set()); };
43	
44	  const handleMarcar = async () => {
45	    await onMarcarProntos({ pedidoIds: [...pedidosSel], itemIds: [...itensSel] });
46	    selecionarNenhum();
47	  };
48	
49	  return (
50	    <>
51	      <div className="text-center mb-4">
52	        <p className="text-2xl mb-1">👨‍🍳</p>
53	        <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">Pedidos ainda em preparo</h2>
54	        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">
55	          {totalItens} {totalItens === 1 ? 'item está' : 'itens estão'} em produção. Marque como pronto o que já terminou, ou continue deixando pendente.
56	        </p>
57	      </div>
58	
59	      <div className="flex justify-end gap-2 mb-2">
60	        <button onClick={selecionarTodos} className="text-[11px] font-bold text-[#FF441F] hover:underline">Selecionar todos</button>
61	        <span className="text-[#E4E4E7] dark:text-[#3F3F46]">|</span>
62	        <button onClick={selecionarNenhum} className="text-[11px] font-bold text-[#71717A] dark:text-[#A1A1AA] hover:underline">Nenhum</button>
63	      </div>
64	
65	      {pedidosEmPreparo.length > 0 && (
66	        <div className="mb-3">
67	          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1">Pedidos delivery/balcão</p>
68	          <div className="bg-orange-50 dark:bg-orange-950/40 rounded-xl p-3 max-h-40 overflow-y-auto space-y-1">
69	            {pedidosEmPreparo.map((p) => (
70	              <label key={p.id} className="flex items-center gap-2 text-xs py-1 cursor-pointer">
71	                <input type="checkbox" checked={pedidosSel.has(p.id)} onChange={() => toggle(setPedidosSel, p.id)}
72	                  className="accent-[#FF441F]" />
73	                <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">#{p.id}</span>
74	                <span className="text-[#71717A] dark:text-[#A1A1AA] flex-1 text-right">{fmt(p.total)} · Em preparo</span>
75	              </label>
76	            ))}
77	          </div>
78	        </div>
79	      )}
80	
81	      {itensEmPreparo.length > 0 && (
82	        <div className="mb-3">
83	          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1">Itens de comanda (salão)</p>
84	          <div className="bg-orange-50 dark:bg-orange-950/40 rounded-xl p-3 max-h-40 overflow-y-auto space-y-1">
85	            {itensEmPreparo.map((i) => (
86	              <label key={i.id} className="flex items-center gap-2 text-xs py-1 cursor-pointer">
87	                <input type="checkbox" checked={itensSel.has(i.id)} onChange={() => toggle(setItensSel, i.id)}
88	                  className="accent-[#FF441F]" />
89	                <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{i.quantity}x {i.products?.name ?? 'Item'}</span>
90	                <span className="text-[#71717A] dark:text-[#A1A1AA] flex-1 text-right">{labelComanda(i.orders)} · {ITEM_STATUS_LABEL[i.status] ?? i.status}</span>
91	              </label>
92	            ))}
93	          </div>
94	        </div>
95	      )}
96	
97	      <div className="flex gap-2 mb-2">
98	        <button onClick={onCancelar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Cancelar</button>
99	        <button onClick={handleMarcar} disabled={marcando || totalSel === 0}
100	          className="flex-1 py-2.5 text-sm bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 disabled:opacity-50">
101	          {marcando ? 'Marcando...' : `Marcar ${totalSel || ''} como pronto`}
102	        </button>
103	      </div>
104	      <button onClick={onContinuar} className="w-full py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">
105	        Continuar sem marcar (deixar em preparo)
106	      </button>
107	      <p className="text-[10px] text-[#A1A1AA] mt-1.5 text-center">
108	        O que ficar em preparo continua contando como pendência — você poderá transferir para outro operador ou fechar mesmo assim na próxima etapa.
109	      </p>
110	    </>
111	  );
112	};
113	
114	// ── Tela 1: pedidos/comandas/mesas em aberto ──────────────────────────────────
115	const PedidosAbertosView = ({ pedidosAbertos, comandasAbertas, mesasAbertas, onTransferir, onFecharComPendencia, onAceitarSelecionadas, onCancelar, fechando }) => {
116	  const [novoOperador, setNovoOperador] = useState('');
117	  const [novoValor, setNovoValor] = useState('');
118	  const [modoTransf, setModoTransf] = useState(false);
119	  const [comandasSel, setComandasSel] = useState(new Set());
120	  const [mesasSel, setMesasSel] = useState(new Set());
121	  const totalPendencias = pedidosAbertos.length + comandasAbertas.length + mesasAbertas.length;
122	  const totalSelecionavel = comandasAbertas.length + mesasAbertas.length;
123	  const totalSel = comandasSel.size + mesasSel.size;
124	
125	  const toggle = (setFn, id) => setFn((prev) => {
126	    const next = new Set(prev);
127	    next.has(id) ? next.delete(id) : next.add(id);
128	    return next;
129	  });
130	  const selecionarTodasPendencias = () => {
131	    setComandasSel(new Set(comandasAbertas.map((c) => c.id)));
132	    setMesasSel(new Set(mesasAbertas.map((m) => m.id)));
133	  };
134	  const selecionarNenhumaPendencia = () => { setComandasSel(new Set()); setMesasSel(new Set()); };
135	
136	  if (modoTransf) return (
137	    <>
138	      <div className="text-center mb-4">
139	        <p className="text-2xl mb-1">🔄</p>
140	        <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">Transferir e Abrir Novo Caixa</h2>
141	        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">{totalPendencias} pedido(s)/comanda(s) serão transferidos</p>
142	      </div>
143	      <div className="space-y-3 mb-4">
144	        <div>
145	          <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Operador do novo caixa *</label>
146	          <input value={novoOperador} onChange={(e) => setNovoOperador(e.target.value)} placeholder="Ex: João"
147	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
148	        </div>
149	        <div>
150	          <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Valor inicial do novo caixa (R$)</label>
151	          <input type="number" min="0" step="0.01" value={novoValor} onChange={(e) => setNovoValor(e.target.value)} placeholder="0,00"
152	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
153	        </div>
154	      </div>
155	      <div className="flex gap-2">
156	        <button onClick={() => setModoTransf(false)} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Voltar</button>
157	        <button onClick={() => onTransferir({ nome_operador: novoOperador.trim(), valor_inicial: parseFloat(novoValor) || 0 })}
158	          disabled={fechando || !novoOperador.trim()}
159	          className="flex-1 py-2.5 text-sm bg-[#FF441F] text-white rounded-xl font-bold hover:bg-[#E63A19] disabled:opacity-50">
160	          {fechando ? 'Transferindo...' : 'Confirmar'}
161	        </button>
162	      </div>
163	    </>
164	  );
165	
166	  return (
167	    <>
168	      <div className="text-center mb-4">
169	        <p className="text-2xl mb-1">⚠️</p>
170	        <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">Pendências em Aberto</h2>
171	        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">Caixa não pode fechar com pedidos, comandas ou mesas em andamento</p>
172	      </div>
173	      {pedidosAbertos.length > 0 && (
174	        <div className="mb-3">
175	          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1">Pedidos delivery</p>
176	          <div className="bg-orange-50 dark:bg-orange-950/40 rounded-xl p-3 max-h-32 overflow-y-auto">
177	            {pedidosAbertos.map((p) => (
178	              <div key={p.id} className="flex justify-between text-xs py-1 border-b border-orange-100 dark:border-orange-900/40 last:border-0">
