191	            <button onClick={selecionarNenhumaPendencia} className="text-[11px] font-bold text-[#71717A] dark:text-[#A1A1AA] hover:underline">Nenhuma</button>
192	          </div>
193	        </div>
194	      )}
195	      {comandasAbertas.length > 0 && (
196	        <div className="mb-3">
