async fecharCaixa(restaurantId: number, body?: { dinheiro_contado?: number; permitir_pendencias?: boolean }) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('*').eq('restaurant_id', restaurantId)
    .in('status', ['aberto', 'expirado']).maybeSingle();

  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  // Escopado por restaurant_id (não caixa_id) — igual mesasAbertas abaixo. Uma comanda/pedido
  // deixado pendente num fechamento anterior ("fiado, cobrado no próximo caixa aberto") continua
  // com caixa_id apontando pro caixa antigo já fechado; filtrar por caixa_id do caixa atual fazia
  // essas pendências carregadas ficarem invisíveis pra sempre nos fechamentos seguintes.
  const { data: pedidosAbertos } = await this.supabase.client
    .from('orders').select('id, status, total')
    .eq('restaurant_id', restaurantId)
    .in('status', this.STATUS_ABERTOS);

  const { data: comandasAbertas } = await this.supabase.client
    .from('orders')
    .select('id, status, mesa_id, mesas(numero, nome)')
    .eq('restaurant_id', restaurantId)
    .eq('canal', 'presencial')
    .in('status', this.COMANDA_STATUS_ABERTOS);

  const { data: mesasAbertas } = await this.supabase.client
    .from('mesas')
    .select('id, numero, nome, status')
    .eq('restaurant_id', restaurantId)
    .neq('status', 'livre');

  const temPendencias = (pedidosAbertos ?? []).length > 0 || (comandasAbertas ?? []).length > 0 || (mesasAbertas ?? []).length > 0;

  if (temPendencias && !body?.permitir_pendencias) {
    // Recorte de "ainda em produção" dentro das pendências acima — pedidos delivery/balcão
    // parados em 'confirmed' (Aguardando Preparo) ou 'preparing' (Em Preparo), e itens de
    // comanda ainda não marcados 'pronto' (enviado ou preparando). É só informativo pro
    // operador decidir o que avançar antes de fechar; não muda o bloqueio em si (que
    // continua sendo pedidosAbertos/comandasAbertas/mesasAbertas).
    const pedidosEmPreparo = (pedidosAbertos ?? []).filter((p: any) => p.status === 'confirmed' || p.status === 'preparing');

    const idsComandasAbertas = (comandasAbertas ?? []).map((c: any) => c.id);
    const { data: itensEmPreparo } = idsComandasAbertas.length
      ? await this.supabase.client
          .from('order_items')
          .select('id, order_id, quantity, status, products(name), orders(numero_comanda, mesa_id, cliente_mesa_nome, mesas(numero, nome))')
          .in('order_id', idsComandasAbertas)
          .in('status', ['enviado', 'preparando'])
      : { data: [] as any[] };

    throw new ConflictException({
      message: 'Existem pendências em aberto: feche os pedidos, comandas e mesas antes de fechar o caixa',
      pedidos_abertos: pedidosAbertos?.length ?? 0,
      pedidos: pedidosAbertos ?? [],
      comandas_abertas: comandasAbertas?.length ?? 0,
      comandas: comandasAbertas ?? [],
      mesas_abertas: mesasAbertas?.length ?? 0,
      mesas: mesasAbertas ?? [],
      pedidos_em_preparo: pedidosEmPreparo,
      itens_em_preparo: itensEmPreparo ?? [],
    });
  }

  // Mesa não pode ficar travada esperando o caixa reabrir — libera pro próximo
  // cliente e a pendência (se houver comanda em aberto) segue como fiado,
  // cobrada no caixa aberto quando o pagamento acontecer.
  if ((mesasAbertas ?? []).length > 0) {
    await this.supabase.client
      .from('mesas')
      .update({ status: 'livre' })
      .in('id', (mesasAbertas ?? []).map((m) => m.id));
  }

  const { data: todosPedidos } = await this.supabase.client
    .from('orders').select('id, total, status, payment_method, canal, created_at')
    .or(`caixa_id.eq.${caixa.id},and(caixa_id.is.null,created_at.gte.${caixa.aberto_em})`);

  const saidas = (caixa.saidas ?? []) as any[];
  const entradas = (caixa.entradas ?? []) as any[];
  const pagamentosPorComanda = await this.buscarPagamentosPorComanda(todosPedidos ?? []);
  const resumo = this.calcularResumo(todosPedidos ?? [], saidas, caixa.valor_inicial, entradas, pagamentosPorComanda);
  const fechado_em = new Date().toISOString();

  // Conferência: operador informa quanto contou; sistema compara com espécie calculada
  const dinheiro_contado = body?.dinheiro_contado ?? (resumo.especie_calculada ?? 0);
  const diferenca = dinheiro_contado - (resumo.especie_calculada ?? 0);
  const destinacao_fechamento = {
    dinheiro_contado,
    especie_calculada: resumo.especie_calculada,
    diferenca,
    por_pagamento: resumo.por_pagamento,
    conferencia_aprovada: false,
  };

  await this.supabase.client.from('caixas')
    .update({
      status: 'fechado', fechado_em, resumo, destinacao_fechamento,
      fechado_com_pendencias: temPendencias,
      pendencias_fechamento: temPendencias
        ? { pedidos: pedidosAbertos ?? [], comandas: comandasAbertas ?? [], mesas: mesasAbertas ?? [] }
        : null,
    })

import React, { useState } from 'react';
import { getSalaoComandaDetalhe } from '../../services/restauranteService';

const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
const fmtDate = (d) => d ? new Date(d).toLocaleString('pt-BR') : '-';

const PL = { cash: 'Dinheiro', pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', taxa_cartao: '+ Taxa cartão' };
const PEDIDO_STATUS_LABEL = { confirmed: 'Aguardando Preparo', preparing: 'Em preparo' };

const Row = ({ label, value, bold, accent, muted }) => (
  <div className={`flex justify-between text-sm py-1.5 border-b border-[#F4F4F5] dark:border-[#3F3F46] last:border-0 ${bold ? 'font-bold' : ''}`}>
    <span className={muted ? 'text-[#A1A1AA]' : 'text-[#71717A] dark:text-[#A1A1AA]'}>{label}</span>
    <span className={accent ? 'text-[#FF441F] font-bold' : muted ? 'text-[#A1A1AA]' : 'text-[#18181B] dark:text-[#F4F4F5]'}>{value}</span>
  </div>
);

// ── Tela 0: pedidos/itens ainda em preparo/produção ───────────────────────────
const ITEM_STATUS_LABEL = { enviado: 'Aguardando', preparando: 'Em preparo' };

const labelComanda = (order) => {
  if (order?.mesas) return `Mesa ${order.mesas.numero}${order.mesas.nome ? ` - ${order.mesas.nome}` : ''}`;
  if (order?.numero_comanda) return `Comanda #${order.numero_comanda}`;
  if (order?.cliente_mesa_nome) return order.cliente_mesa_nome;
  return 'Comanda';
};

const PreparoEmAndamentoView = ({ pedidosEmPreparo, itensEmPreparo, onMarcarProntos, marcando, onContinuar, onCancelar }) => {
  const [pedidosSel, setPedidosSel] = useState(new Set());
  const [itensSel, setItensSel] = useState(new Set());

  const totalItens = pedidosEmPreparo.length + itensEmPreparo.length;
  const totalSel = pedidosSel.size + itensSel.size;

  const toggle = (setFn, id) => setFn((prev) => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });

  const selecionarTodos = () => {
    setPedidosSel(new Set(pedidosEmPreparo.map((p) => p.id)));
    setItensSel(new Set(itensEmPreparo.map((i) => i.id)));
  };
  const selecionarNenhum = () => { setPedidosSel(new Set()); setItensSel(new Set()); };

  const handleMarcar = async () => {
    await onMarcarProntos({ pedidoIds: [...pedidosSel], itemIds: [...itensSel] });
    selecionarNenhum();
  };

  return (
    <>
      <div className="text-center mb-4">
        <p className="text-2xl mb-1">👨‍🍳</p>
        <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">Pedidos ainda em preparo</h2>
        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">
          {totalItens} {totalItens === 1 ? 'item está' : 'itens estão'} em produção. Marque como pronto o que já terminou, ou continue deixando pendente.
        </p>
      </div>

      <div className="flex justify-end gap-2 mb-2">
        <button onClick={selecionarTodos} className="text-[11px] font-bold text-[#FF441F] hover:underline">Selecionar todos</button>
        <span className="text-[#E4E4E7] dark:text-[#3F3F46]">|</span>
        <button onClick={selecionarNenhum} className="text-[11px] font-bold text-[#71717A] dark:text-[#A1A1AA] hover:underline">Nenhum</button>
      </div>

      {pedidosEmPreparo.length > 0 && (
        <div className="mb-3">
          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1">Pedidos delivery/balcão</p>
          <div className="bg-orange-50 dark:bg-orange-950/40 rounded-xl p-3 max-h-40 overflow-y-auto space-y-1">
            {pedidosEmPreparo.map((p) => (
              <label key={p.id} className="flex items-center gap-2 text-xs py-1 cursor-pointer">
                <input type="checkbox" checked={pedidosSel.has(p.id)} onChange={() => toggle(setPedidosSel, p.id)}
                  className="accent-[#FF441F]" />
                <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">#{p.id}</span>
                <span className="text-[#71717A] dark:text-[#A1A1AA] flex-1 text-right">{fmt(p.total)} · {PEDIDO_STATUS_LABEL[p.status] ?? p.status}</span>
              </label>
            ))}
          </div>
        </div>
      )}

      {itensEmPreparo.length > 0 && (
        <div className="mb-3">
          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1">Itens de comanda (salão)</p>
          <div className="bg-orange-50 dark:bg-orange-950/40 rounded-xl p-3 max-h-40 overflow-y-auto space-y-1">
            {itensEmPreparo.map((i) => (
              <label key={i.id} className="flex items-center gap-2 text-xs py-1 cursor-pointer">
                <input type="checkbox" checked={itensSel.has(i.id)} onChange={() => toggle(setItensSel, i.id)}
                  className="accent-[#FF441F]" />
                <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{i.quantity}x {i.products?.name ?? 'Item'}</span>
                <span className="text-[#71717A] dark:text-[#A1A1AA] flex-1 text-right">{labelComanda(i.orders)} · {ITEM_STATUS_LABEL[i.status] ?? i.status}</span>
              </label>
            ))}
          </div>
        </div>
      )}

      <div className="flex gap-2 mb-2">
        <button onClick={onCancelar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Cancelar</button>
        <button onClick={handleMarcar} disabled={marcando || totalSel === 0}
          className="flex-1 py-2.5 text-sm bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 disabled:opacity-50">
          {marcando ? 'Marcando...' : `Marcar ${totalSel || ''} como pronto`}
        </button>
      </div>
      <button onClick={onContinuar} className="w-full py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">
        Continuar sem marcar (deixar em preparo)
      </button>
      <p className="text-[10px] text-[#A1A1AA] mt-1.5 text-center">
        O que ficar em preparo continua contando como pendência — você poderá transferir para outro operador ou fechar mesmo assim na próxima etapa.
      </p>
    </>
  );
};

// ── Tela 1: pedidos/comandas/mesas em aberto ──────────────────────────────────
const ComandaLinha = ({ comanda, selecionada, onToggle, expandida, onToggleExpandir, detalhe, carregandoDetalhe }) => (
  <div className="border-b border-orange-100 dark:border-orange-900/40 last:border-0">
    <div className="flex items-center gap-2 text-xs py-1">
      <input type="checkbox" checked={selecionada} onChange={onToggle} className="accent-red-500 flex-shrink-0" />
      <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{comanda.mesas ? `Mesa ${comanda.mesas.numero}` : `Comanda #${comanda.id}`}</span>
      <span className="text-[#71717A] dark:text-[#A1A1AA] flex-1 text-right">{comanda.status === 'aberta' ? 'Em aberto' : 'Aguard. pagamento'}</span>
      <button type="button" onClick={onToggleExpandir} className="text-[10px] font-bold text-[#FF441F] hover:underline flex-shrink-0">
        {expandida ? 'Ocultar' : 'Ver tudo'}
      </button>
    </div>
    {expandida && (
      <div className="ml-6 mb-1.5 bg-white/70 dark:bg-black/20 rounded-lg p-2 space-y-2">
        {carregandoDetalhe ? (
          <p className="text-[10px] text-[#A1A1AA]">Carregando...</p>
        ) : !detalhe ? (
          <p className="text-[10px] text-red-500">Não foi possível carregar os dados da comanda.</p>
        ) : (
          <>
            <div className="text-[10px] text-[#71717A] dark:text-[#A1A1AA] space-y-0.5">
              <p>Garçom: <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{detalhe.garcons?.nome ?? '—'}</span></p>
              <p>Cliente: <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{detalhe.cliente_mesa_nome || '—'}</span></p>
              {detalhe.numero_comanda && <p>Comanda nº: <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{detalhe.numero_comanda}</span></p>}
              <p>Aberta em: <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{fmtDate(detalhe.created_at)}</span></p>
              <p>Total: <span className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">{fmt(detalhe.total)}</span></p>
            </div>

            <div>
              <p className="text-[9px] font-black text-[#A1A1AA] uppercase tracking-widest mb-0.5">Itens</p>
              {detalhe.itens?.length ? detalhe.itens.map((it) => (
                <div key={it.id} className="flex justify-between text-[10px] py-0.5">
                  <span className="text-[#18181B] dark:text-[#F4F4F5]">{it.quantity}x {it.products?.name ?? 'Item'}{it.observacao ? ` (${it.observacao})` : ''}</span>
                  <span className="text-[#A1A1AA]">{it.status}</span>
                </div>
              )) : <p className="text-[10px] text-green-600 dark:text-green-400">Nenhum item lançado — comanda vazia, pode excluir sem risco.</p>}
            </div>

            <div>
              <p className="text-[9px] font-black text-[#A1A1AA] uppercase tracking-widest mb-0.5">Pagamentos</p>
              {detalhe.pagamentos?.length ? detalhe.pagamentos.map((pg) => (
                <div key={pg.id} className="flex justify-between text-[10px] py-0.5">
                  <span className="text-[#18181B] dark:text-[#F4F4F5]">{PL[pg.forma_pagamento] ?? pg.forma_pagamento} · {pg.origem}</span>
                  <span className="text-[#A1A1AA]">{fmt(pg.valor)} · {fmtDate(pg.criado_em)}</span>
                </div>
              )) : <p className="text-[10px] text-[#A1A1AA]">Nenhum pagamento registrado.</p>}
            </div>

            {detalhe.saldo > 0 && (
              <p className="text-[10px] font-bold text-amber-600 dark:text-amber-400">Saldo devedor: {fmt(detalhe.saldo)} — excluir estorna os pagamentos já lançados</p>
            )}

