                  <span className="text-[#A1A1AA]">{fmt(pg.valor)} · {fmtDate(pg.criado_em)}</span>
                </div>
              )) : <p className="text-[10px] text-[#A1A1AA]">Nenhum pagamento registrado.</p>}
            </div>

