// Fila de preparo do restaurante inteiro (não só as comandas do garçom logado) — o
// garçom usa isso pra responder ao cliente presencial "quantos faltam antes do meu"
// e "quanto tempo em média demora", sem precisar ir até a cozinha.
async filaCozinha(restaurantId: number) {
  const { data: itensRaw, error } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, quantity, status, enviado_em, preparando_em, products(name), orders!inner(restaurant_id, canal, status, numero_comanda, cliente_mesa_nome, mesas(numero, nome))')
    .eq('orders.restaurant_id', restaurantId)
    .eq('orders.canal', 'presencial')
    .in('orders.status', ['aberta', 'fechada_garcom'])
    .in('status', ['enviado', 'preparando'])
    .order('enviado_em', { ascending: true });
  if (error) throw error;

  const itens = (itensRaw ?? []).map((i: any) => ({
    item_id: i.id,
    order_id: i.order_id,
    numero_comanda: i.orders?.numero_comanda ?? i.order_id,
    mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
    cliente_mesa_nome: i.orders?.cliente_mesa_nome ?? null,
    product_name: i.products?.name,
    quantity: i.quantity,
    status: i.status,
    enviado_em: i.enviado_em,
    preparando_em: i.preparando_em,
  }));

  // Três médias, sobre itens finalizados hoje: espera (na fila, antes do preparo
  // começar), preparo (tempo ativo de cozinha) e geral (soma das duas, o que o
  // cliente sente desde que pediu até ficar pronto).
  const inicioHoje = new Date();
  inicioHoje.setHours(0, 0, 0, 0);
  const { data: prontosHoje } = await this.supabase.client
    .from('order_items')
    .select('enviado_em, preparando_em, pronto_em, orders!inner(restaurant_id, canal)')
    .eq('orders.restaurant_id', restaurantId)
    .eq('orders.canal', 'presencial')
    .eq('status', 'pronto')
    .not('enviado_em', 'is', null)
    .not('preparando_em', 'is', null)
    .not('pronto_em', 'is', null)
    .gte('pronto_em', inicioHoje.toISOString())

async fecharCaixa(restaurantId: number, body?: { dinheiro_contado?: number; permitir_pendencias?: boolean }) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('*').eq('restaurant_id', restaurantId)
    .in('status', ['aberto', 'expirado']).maybeSingle();

  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  // Escopado por restaurant_id (não caixa_id) — igual mesasAbertas abaixo. Uma comanda/pedido
  // deixado pendente num fechamento anterior ("fiado, cobrado no próximo caixa aberto") continua
  // com caixa_id apontando pro caixa antigo já fechado; filtrar por caixa_id do caixa atual fazia
  // essas pendências carregadas ficarem invisíveis pra sempre nos fechamentos seguintes.
  const { data: pedidosAbertos } = await this.supabase.client
    .from('orders').select('id, status, total')
    .eq('restaurant_id', restaurantId)
    .in('status', this.STATUS_ABERTOS);

  const { data: comandasAbertas } = await this.supabase.client
    .from('orders')
    .select('id, status, mesa_id, mesas(numero, nome)')
    .eq('restaurant_id', restaurantId)
    .eq('canal', 'presencial')
    .in('status', this.COMANDA_STATUS_ABERTOS);

  const { data: mesasAbertas } = await this.supabase.client
    .from('mesas')
    .select('id, numero, nome, status')
    .eq('restaurant_id', restaurantId)
    .neq('status', 'livre');

  const temPendencias = (pedidosAbertos ?? []).length > 0 || (comandasAbertas ?? []).length > 0 || (mesasAbertas ?? []).length > 0;

  if (temPendencias && !body?.permitir_pendencias) {
    // Recorte de "ainda em produção" dentro das pendências acima — pedidos delivery/balcão
    // parados em 'confirmed' (Aguardando Preparo) ou 'preparing' (Em Preparo), e itens de
    // comanda ainda não marcados 'pronto' (enviado ou preparando). É só informativo pro
    // operador decidir o que avançar antes de fechar; não muda o bloqueio em si (que
    // continua sendo pedidosAbertos/comandasAbertas/mesasAbertas).
    const pedidosEmPreparo = (pedidosAbertos ?? []).filter((p: any) => p.status === 'confirmed' || p.status === 'preparing');

    const idsComandasAbertas = (comandasAbertas ?? []).map((c: any) => c.id);
    const { data: itensEmPreparo } = idsComandasAbertas.length
      ? await this.supabase.client
          .from('order_items')
          .select('id, order_id, quantity, status, products(name), orders(numero_comanda, mesa_id, cliente_mesa_nome, mesas(numero, nome))')
          .in('order_id', idsComandasAbertas)
          .in('status', ['enviado', 'preparando'])
      : { data: [] as any[] };

    throw new ConflictException({
      message: 'Existem pendências em aberto: feche os pedidos, comandas e mesas antes de fechar o caixa',
      pedidos_abertos: pedidosAbertos?.length ?? 0,
      pedidos: pedidosAbertos ?? [],
      comandas_abertas: comandasAbertas?.length ?? 0,
      comandas: comandasAbertas ?? [],
      mesas_abertas: mesasAbertas?.length ?? 0,

