450	  async abrirComanda(garcomId: number, restaurantId: number, body: AbrirComandaBody, restauranteAberto?: boolean, salaoModo: 'mesas' | 'comandas' | 'ambos' = 'ambos') {
451	    if (!restauranteAberto) {
452	      throw new ForbiddenException('Restaurante fechado — não é possível abrir mesa/comanda');
453	    }
454	    if (salaoModo === 'mesas' && !body.mesa_id) {
455	      throw new BadRequestException('Este restaurante só trabalha com mesas — selecione uma mesa');
456	    }
457	    if (salaoModo === 'comandas' && body.mesa_id) {
458	      throw new BadRequestException('Este restaurante só trabalha com comandas avulsas — não vincule a uma mesa');
459	    }
460	    if (!body.cliente_nome || !body.cliente_telefone) {
461	      throw new BadRequestException('Nome e telefone do cliente são obrigatórios');
462	    }
463	
464	    let mesa: { id: number } | null = null;
465	    if (body.mesa_id) {
466	      const { data } = await this.supabase.client
467	        .from('mesas')
468	        .select('id, status')
469	        .eq('id', body.mesa_id)
470	        .eq('restaurant_id', restaurantId)
471	        .maybeSingle();
472	      if (!data) throw new NotFoundException('Mesa não encontrada');
473	      if (data.status !== 'livre') throw new BadRequestException('Mesa não está livre');
474	      mesa = data;
475	    }
476	
477	    const { data: caixaAberto } = await this.supabase.client
478	      .from('caixas')
479	      .select('id')
480	      .eq('restaurant_id', restaurantId)
481	      .eq('status', 'aberto')
482	      .maybeSingle();
483	
484	    // Numeração sequencial por dia — só pra identificação fácil ("comanda 3"), reinicia
485	    // a cada dia. Não precisa ser à prova de corrida (volume baixo de comandas simultâneas).
486	    const inicioDoDia = new Date();
487	    inicioDoDia.setHours(0, 0, 0, 0);
488	    const { count } = await this.supabase.client
489	      .from('orders')
490	      .select('id', { count: 'exact', head: true })
491	      .eq('restaurant_id', restaurantId)
492	      .eq('canal', 'presencial')
493	      .gte('created_at', inicioDoDia.toISOString());
