1	import { CanActivate, ExecutionContext, Injectable, ForbiddenException, UnauthorizedException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as jwt from 'jsonwebtoken';
4	import { SupabaseService } from '../supabase/supabase.service';
5	
6	export interface GarcomJwtPayload {
7	  garcomId: number;
8	  sessionId: string;
9	}
10	
11	@Injectable()
12	export class GarcomGuard implements CanActivate {
13	  constructor(
14	    private supabase: SupabaseService,
15	    private config: ConfigService,
16	  ) {}
17	
18	  async canActivate(context: ExecutionContext): Promise<boolean> {
19	    const request = context.switchToHttp().getRequest();
20	    const token = request.headers['x-garcom-token'] as string | undefined;
21	
22	    if (!token) throw new UnauthorizedException('Token de garçom necessário');
23	
24	    let payload: (jwt.JwtPayload & GarcomJwtPayload) | null = null;
25	    try {
26	      const secret = this.config.getOrThrow('GARCOM_JWT_SECRET');
27	      payload = jwt.verify(token, secret) as jwt.JwtPayload & GarcomJwtPayload;
28	    } catch {
29	      throw new UnauthorizedException('Token inválido ou expirado');
30	    }
31	
32	    const { data } = await this.supabase.client
33	      .from('garcons')
34	      .select('id, restaurant_id, nome, ativo, permissoes, active_session_id, session_expires_at, restaurants(aparencia, salao_modo)')
35	      .eq('id', payload.garcomId)
36	      .maybeSingle();
37	
38	    if (!data) throw new UnauthorizedException('Garçom não encontrado');
39	    if (!data.ativo) throw new ForbiddenException('Acesso desativado');
40	
41	    const sessaoValida =
42	      data.active_session_id === payload.sessionId &&
43	      !!data.session_expires_at &&
44	      new Date(data.session_expires_at).getTime() > Date.now();
45	    if (!sessaoValida) throw new UnauthorizedException('Sessão encerrada. Faça login novamente.');
46	
47	    const restauranteAberto = (data as any).restaurants?.aparencia?.aberto === true;
48	    if (!restauranteAberto) throw new ForbiddenException('Restaurante fechado. Aguarde o caixa ser aberto para entrar.');
49	
50	    request.garcomId = data.id;
51	    request.garcomNome = data.nome;
