3	import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, getMinhaEmpresa } from '../../services/restauranteService';
4	import { formatDuracao } from '../../utils/formatDuracao';
5	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
6	import { useNowTick } from '../../hooks/useNowTick';
7	import Icon from '../../components/AppIcon';
8	
9	// Card por item (não por mesa/comanda) — pedido explícito: cada prato tem sua própria
10	// ação de Liberado pra Motoboy/Reimpressão/Entregue, ordenados por ordem de chegada.
11	// `posicao` numera a fila (1º = próximo a sair) pra equipe saber quem vem primeiro.
12	// Cronômetro ao vivo (espera/preparo) igual ao painel de Produção.
13	//
14	// Alerta de motoboy (só item de delivery, com pedido já despachado): pisca amarelo em
15	// trânsito, verde quando entregou, vermelho se o motoboy registrou ocorrência — dados
16	// vêm do pedido (orders.status/motoboy_lat/lng/delivery_occurrence) via getKdsSetor.
17	const AlertaMotoboy = ({ item }) => {
18	  if (item.tipo !== 'delivery') return null;
19	  const temOcorrencia = item.delivery_occurrence === 'pendente';
20	  const entregue = item.pedido_status === 'delivered';
21	  const emTransito = item.pedido_status === 'out_for_delivery' || item.pedido_status === 'motoboy_collecting';
22	  const temMapa = item.motoboy_lat != null && item.motoboy_lng != null;
23	
24	  if (!temOcorrencia && !entregue && !emTransito && !temMapa) return null;
25	
26	  const cor = temOcorrencia ? 'bg-red-500' : entregue ? 'bg-emerald-500' : emTransito ? 'bg-yellow-400' : null;
27	  const label = temOcorrencia ? 'Ocorrência do motoboy' : entregue ? 'Entregue' : emTransito ? 'Motoboy em trânsito' : '';
28	
29	  return (
30	    <div className="flex items-center gap-1.5 flex-shrink-0">
31	      {cor && <span className={`w-2.5 h-2.5 rounded-full ${cor} animate-pulse`} title={label} />}
32	      {temMapa && (
33	        <a href={`https://www.google.com/maps?q=${item.motoboy_lat},${item.motoboy_lng}`} target="_blank" rel="noopener noreferrer"
34	          className="p-1 text-[#71717A] hover:text-white rounded-md hover:bg-[#2A2A2A]" title="Localizar motoboy no mapa">
35	          <Icon name="MapPin" size={13} />
36	        </a>
37	      )}
38	    </div>
39	  );
40	};
41	
42	const ItemCard = ({ item, posicao, now, onIniciarPreparo, onMarcarPronto, onVoltar, highlighted = false }) => {
43	  const enviadoEm = new Date(item.enviado_em).getTime();
44	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
45	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
46	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
47	  const tempoTotal = now - enviadoEm;
48	
49	  return (
50	  <div id={`bar-item-${item.id}`} className={`bg-[#1A1A1A] border rounded-2xl overflow-hidden relative transition-all duration-300 ${
51	    highlighted
52	      ? 'border-yellow-400 ring-2 ring-yellow-400/60 shadow-xl shadow-yellow-300/20 scale-[1.02]'
53	      : item.garcom_nao_entregou ? 'border-red-500 ring-1 ring-red-500/40' : posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'
54	  }`}>
55	    {item.garcom && (
56	      <div className="bg-white px-4 py-2">
57	        <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
58	      </div>
59	    )}
60	    <div className="p-4">
61	    <div className="flex items-start justify-between mb-1 gap-2">
62	      <div className="flex items-start gap-2">
63	        <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
64	          {posicao}
65	        </span>
66	        <div className="leading-tight">
67	          <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
68	          <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
69	        </div>
70	      </div>
71	      <div className="flex items-center gap-1.5 flex-shrink-0">
72	        <AlertaMotoboy item={item} />
73	      </div>
74	    </div>
75	    {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
76	    {item.garcom_nao_entregou && (
77	      <p className="text-sm font-bold text-white bg-red-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">
78	        Esse pedido não foi entregue — garçom não entregou
79	      </p>
80	    )}
81	    {item.is_auto_atendimento && (
82	      <p className="text-sm font-bold text-white bg-pink-600 rounded px-1.5 py-0.5 mb-1">
83	        Auto Atendimento — Mesa {item.mesa_numero ?? '?'}
84	      </p>
85	    )}
86	    {item.garcom_indo_buscar && (
87	      <p className={`text-sm font-bold text-white rounded px-1.5 py-0.5 mb-1 ${item.entregue_garcom ? 'bg-emerald-600' : 'bg-blue-600'}`}>
88	        {item.entregue_garcom ? 'Já entregue pelo garçom' : 'Garçom vindo buscar'}
89	      </p>
90	    )}
91	    {item.observacao && <p className="text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">Obs: {item.observacao}</p>}
92	    <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
93	      <Icon name="MapPin" size={14} />
94	      <span>{item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
95	      {item.numero_comanda && (
96	        <>
97	          <span className="text-[#71717A]">•</span>
98	          <span>Comanda #{item.numero_comanda}</span>
99	        </>
100	      )}
101	      <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
102	        {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
103	      </span>
104	    </div>
105	    <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
106	      <span className="flex items-center gap-1 text-blue-400">
107	        <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
108	      </span>
109	      {item.status === 'preparando' && (
110	        <span className="flex items-center gap-1 text-orange-400">
111	          <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
112	        </span>
113	      )}
114	      <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
115	    </div>
116	    <div className="flex gap-2">
117	      {item.status !== 'enviado' && (
118	        <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
119	          className="flex-shrink-0 px-3 py-2 bg-[#2A2A2A] hover:bg-[#3A3A3A] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
120	          <Icon name="Undo2" size={13} /> Voltar
121	        </button>
122	      )}
123	      {item.status === 'enviado' && (
124	        <button onClick={() => onIniciarPreparo(item)}
125	          className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
126	          <Icon name="ChefHat" size={13} /> Liberado pra Motoboy
127	        </button>
128	      )}
129	      {item.status === 'preparando' && (
130	        <button onClick={() => onMarcarPronto(item.id)}
131	          className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
132	          <Icon name="Check" size={13} /> Entregue
133	        </button>
134	      )}
135	      {item.status === 'pronto' && (
136	        <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
137	          <Icon name="Check" size={13} /> Entregue
138	        </div>
139	      )}
140	    </div>
141	    </div>
142	  </div>
143	  );
144	};
