146	// Painel de pedidos do Bar/Copa — mesmo padrão de acesso da tela de Cozinha (dono já
147	// logado, sem link/token separado), lista PLANA de itens por setor de impressora (não
148	// agrupa por mesa/comanda — cada prato tem seu próprio ritmo e ação). Coexiste com
149	// /restaurante/producao (visão unificada de todos os setores) — essa aqui é só o Bar.
150	const RestauranteBar = () => {
151	  const navigate = useNavigate();
152	  const [impressorasBar, setImpressorasBar] = useState(null);
153	  const [itens, setItens] = useState([]);
154	  const [restauranteNome, setRestauranteNome] = useState('');
155	  const [loading, setLoading] = useState(true);
156	  const [erro, setErro] = useState(null);
157	  const [lastUpdate, setLastUpdate] = useState(null);
158	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
159	  const [busca, setBusca] = useState('');
160	  const [verTodosEntregues, setVerTodosEntregues] = useState(false);
161	  const now = useNowTick();
162	  const prevItemIds = useRef(new Set());
163	  const firstLoad = useRef(true);
164	  const tocarSom = useNotificacaoSonora('cozinha');
165	
166	  useEffect(() => {
167	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
168	    listarImpressoras()
169	      .then((lista) => setImpressorasBar((lista ?? []).filter((i) => (i.setor ?? '').toLowerCase().includes('bar'))))
170	      .catch((e) => setErro(e.message));
171	  }, []);
172	
173	  const carregar = useCallback(async (impressoras) => {
174	    try {
175	      const listas = await Promise.all(
176	        impressoras.map((imp) => getKdsItensRestaurante(imp.id).then((r) => r.itens ?? [])),
177	      );
178	      const todosItens = listas.flat().sort((a, b) => new Date(a.enviado_em).getTime() - new Date(b.enviado_em).getTime());
179	
180	      const idsAgora = new Set(todosItens.map((i) => i.id));
181	      if (!firstLoad.current) {
182	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
183	        if (novos.length > 0) tocarSom();
184	      } else {
185	        firstLoad.current = false;
186	      }
187	      prevItemIds.current = idsAgora;
188	
189	      setItens(todosItens);
190	      setLastUpdate(new Date());
191	      setErro(null);
192	    } catch (e) {
193	      setErro(e.message);
194	    } finally {
195	      setLoading(false);
196	    }
197	  }, [tocarSom]);
198	
199	  useEffect(() => {
200	    if (!impressorasBar) return;
201	    if (impressorasBar.length === 0) { setLoading(false); return; }
202	    carregar(impressorasBar);
203	    const interval = setInterval(() => carregar(impressorasBar), 15000);
204	    return () => clearInterval(interval);
205	  }, [impressorasBar, carregar]);
206	
207	  const marcarPronto = async (itemId) => {
208	    await marcarItemProntoRestaurante(itemId);
209	    carregar(impressorasBar);
210	  };
211	
212	  const iniciarPreparo = async (item) => {
213	    await iniciarPreparoItemRestaurante(item.id);
214	    carregar(impressorasBar);
215	  };
216	
217	  const voltar = async (item) => {
218	    try {
219	      await voltarStatusItemRestaurante(item.id);
220	      carregar(impressorasBar);
221	    } catch (e) {
222	      setErro(e.message);
223	    }
224	  };
225	
226	  if (loading) return (
227	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
228	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
229	    </div>
230	  );
231	
232	  const buscaNormalizada = busca.trim().toLowerCase();
233	  // Leitor de código de barras digita os dígitos zero-padded (ver barcodeValue em
234	  // printComanda.js) e manda Enter — bate exato no numero_comanda, não por substring
235	  // (senão "00000042" nunca acharia a comanda #42).
236	  const numeroComandaEscaneado = /^\d+$/.test(busca.trim()) ? parseInt(busca.trim(), 10) : null;
237	  const passaBusca = (i) => {
238	    if (!buscaNormalizada) return true;
239	    if (numeroComandaEscaneado !== null && i.numero_comanda === numeroComandaEscaneado) return true;
240	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
241	      .filter((v) => v !== null && v !== undefined)
242	      .join(' ')
243	      .toLowerCase();
244	    return alvo.includes(buscaNormalizada);
245	  };
246	  const itensFiltrados = itens.filter((i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i));
247	  const aguardando = itensFiltrados.filter((i) => i.status === 'enviado');
248	  const preparando = itensFiltrados.filter((i) => i.status === 'preparando');
249	  const prontosRecentes = itensFiltrados.filter((i) => i.status === 'pronto')
250	    .sort((a, b) => new Date(b.pronto_em).getTime() - new Date(a.pronto_em).getTime());
251	  const totalDelivery = itens.filter((i) => i.tipo === 'delivery').length;
252	  const totalSalao = itens.filter((i) => i.tipo === 'salao').length;
253	  // Igual à caixa de leitor da Cozinha: verde quando acha a comanda escaneada, vermelho
254	  // quando não acha — só reage ao código exato, busca por nome/mesa/garçom fica neutra.
255	  const itemEncontradoBusca = numeroComandaEscaneado !== null && itens.some((i) => i.numero_comanda === numeroComandaEscaneado);
256	  const corBuscaCod = numeroComandaEscaneado === null ? null : itemEncontradoBusca ? 'ok' : 'erro';
257	
258	  return (
259	    <div className="min-h-screen bg-[#111111]">
260	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
261	        <div className="flex items-center gap-4">
262	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
263	            <Icon name="ArrowLeft" size={18} />
264	          </button>
265	          <div className="flex items-center gap-2">
266	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
267	              <Icon name="Martini" size={16} className="text-white" />
268	            </div>
269	            <div>
270	              <p className="text-white font-black text-base leading-none">Painel do Bar</p>
271	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
272	            </div>
273	          </div>
274	          <div className="ml-auto flex items-center gap-2">
275	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
276	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
277	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
278	            </div>
279	            <button onClick={() => carregar(impressorasBar ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
280	              <Icon name="RefreshCw" size={16} />
281	            </button>
282	          </div>
283	        </div>
284	
285	        {/* Busca por cliente, mesa, comanda, garçom ou leitor de código de barras — mesma
286	            caixa (cor, botão Buscar, texto de confirmação) da Cozinha */}
287	        <div className={`flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border transition-colors ${
288	          corBuscaCod === 'ok' ? 'border-green-500 bg-green-900/20' :
289	          corBuscaCod === 'erro' ? 'border-red-500 bg-red-900/20' :
290	          'border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]'
291	        }`}>
292	          <Icon name="ScanLine" size={16} className={`flex-shrink-0 ${corBuscaCod === 'ok' ? 'text-green-400' : corBuscaCod === 'erro' ? 'text-red-400' : 'text-[#71717A]'}`} />
293	          <input
294	            type="text"
295	            value={busca}
296	            onChange={(e) => setBusca(e.target.value)}
297	            placeholder="Buscar por cliente, mesa, comanda, garçom ou aponte o leitor..."
298	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
299	          />
300	          {busca && (
301	            <>
302	              <button
303	                onClick={() => {
304	                  const alvo = itens.find((i) => i.numero_comanda === numeroComandaEscaneado);
305	                  if (alvo) document.getElementById(`bar-item-${alvo.id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
306	                }}
307	                className="flex-shrink-0 px-3 py-1 bg-[#FF441F] text-white text-xs font-bold rounded-lg hover:bg-[#E63A19]">
308	                Buscar
309	              </button>
310	              <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
311	                <Icon name="X" size={15} />
312	              </button>
313	            </>
314	          )}
315	        </div>
316	        {corBuscaCod && (
317	          <p className={`text-xs font-semibold mt-1.5 ${corBuscaCod === 'ok' ? 'text-green-400' : 'text-red-400'}`}>
318	            {corBuscaCod === 'ok' ? `Comanda #${numeroComandaEscaneado} encontrada` : `Comanda #${numeroComandaEscaneado} não encontrada`}
319	          </p>
320	        )}
321	
322	        {/* Filtro de canal — Todos/Delivery/Salão */}
323	        <div className="flex items-center gap-2 mt-3">
324	          {[
325	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
326	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
327	            { key: 'salao', label: 'Salão', count: totalSalao },
328	          ].map((f) => (
329	            <button
330	              key={f.key}
331	              onClick={() => setFiltroCanal(f.key)}
332	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
333	                filtroCanal === f.key
334	                  ? 'bg-[#FF441F] text-white'
335	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
336	              }`}
337	            >
338	              {f.label}
339	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
340	            </button>
341	          ))}
342	        </div>
343	      </header>
344	
345	      {erro && (
346	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
347	      )}
348	
349	      {impressorasBar && impressorasBar.length === 0 ? (
350	        <div className="text-center py-20 px-5">
351	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
352	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora de setor "Bar" cadastrada</p>
353	          <p className="text-[#3A3A3A] text-sm mt-1">Cadastre uma impressora com o setor "Bar" na tela de Impressoras.</p>
354	          <button onClick={() => navigate('/restaurante/impressoras')}
355	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
356	            Ir pra Impressoras
357	          </button>
358	        </div>
359	      ) : (
360	        <main className="p-5 grid grid-cols-1 lg:grid-cols-2 gap-6 max-w-5xl mx-auto">
361	          <div>
362	            <div className="flex items-center gap-2 mb-3">
363	              <div className="w-3 h-3 rounded-full bg-blue-400" />
364	              <h2 className="text-white font-bold text-sm uppercase tracking-wider">Aguardando Motoboy</h2>
365	              {aguardando.length > 0 && (
366	                <span className="ml-auto bg-blue-500 text-white text-xs font-black px-2 py-0.5 rounded-full">{aguardando.length}</span>
