368	            </div>
369	            {aguardando.length === 0 ? (
370	              <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-8 text-center">
371	                <Icon name="CheckCircle" size={32} className="text-[#3A3A3A] mx-auto mb-2" />
372	                <p className="text-[#71717A] text-sm">Nenhum pedido aguardando</p>
