374	            ) : (
375	              <div className="space-y-3">
376	                {aguardando.map((item, idx) => (
377	                  <ItemCard key={item.id} item={item} posicao={idx + 1} now={now} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltar}
378	                    highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
379	                ))}
380	              </div>
381	            )}
382	          </div>
383	
384	          <div>
385	            <div className="flex items-center gap-2 mb-3">
386	              <div className="w-3 h-3 rounded-full bg-orange-400 animate-pulse" />
387	              <h2 className="text-white font-bold text-sm uppercase tracking-wider">Entregue pra Motoboy</h2>
388	              {preparando.length > 0 && (
389	                <span className="ml-auto bg-orange-500 text-white text-xs font-black px-2 py-0.5 rounded-full">{preparando.length}</span>
390	              )}
