                <Icon name="ChevronDown" size={13} />
              </button>
            </div>
          )}
          <div className="leading-tight">
            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
          </div>
        </div>
