              <p className={`text-xl font-black ${ehDelivery ? 'text-[#18181B] dark:text-[#F4F4F5]' : 'text-white'}`}>Quantidade: {item.quantity}</p>
              <p className={`text-lg font-bold ${ehDelivery ? 'text-[#18181B] dark:text-[#F4F4F5]' : 'text-white'}`}>
