import {
  Body, Controller, Delete, Get, Param, ParseIntPipe,
  Patch, Post, Put, Query, Req, UploadedFile, UseGuards, UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { RestauranteService } from './restaurante.service';
import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
import { SalaoService } from '../salao/salao.service';

@Controller('restaurante')
@UseGuards(RestaurantOwnerGuard)
export class RestauranteController {
  constructor(
    private service: RestauranteService,
    private salaoService: SalaoService,
  ) {}

  @Get('minha-empresa')
  minhaEmpresa(@Req() req: any) {
    return this.service.minhaEmpresa(req.userId);
  }

  @Patch('minha-empresa')
  updateEmpresa(@Req() req: any, @Body() body: any) {
    return this.service.updateEmpresa(req.restaurantId, body);
  }

  @Patch('minha-empresa/localizacao')
  atualizarLocalizacaoManual(@Req() req: any, @Body() body: { lat: number; lng: number }) {
    return this.service.atualizarLocalizacaoManual(req.restaurantId, body.lat, body.lng);
  }

  @Patch('dominio')
  atualizarDominio(@Req() req: any, @Body() body: { custom_domain?: string | null }) {
    return this.service.atualizarDominio(req.restaurantId, body.custom_domain);
  }

  @Patch('dominio/solicitar')
  solicitarRevisaoDominio(@Req() req: any) {
    return this.service.solicitarRevisaoDominio(req.restaurantId);
  }

  @Get('entregas')
  listarEntregas(@Req() req: any) {
    return this.service.listarEntregas(req.restaurantId);
  }

  @Get('pedidos')
  meusPedidos(
    @Req() req: any,
    @Query('status') status?: string,
    @Query('limite') limite?: string,
  ) {
    return this.service.meusPedidos(req.restaurantId, {
      status,
      limite: limite ? parseInt(limite) : undefined,
    });
  }

