1	const crc16 = (str) => {
2	  let crc = 0xFFFF;
3	  for (let i = 0; i < str.length; i++) {
4	    crc ^= str.charCodeAt(i) << 8;
5	    for (let j = 0; j < 8; j++) {
6	      crc = crc & 0x8000 ? (crc << 1) ^ 0x1021 : crc << 1;
7	    }
8	    crc &= 0xFFFF;
9	  }
10	  return crc.toString(16).toUpperCase().padStart(4, '0');
11	};
12	
13	const emv = (id, value) => `${id}${String(value.length).padStart(2, '0')}${value}`;
14	
15	const clean = (str, max) =>
16	  (str ?? '')
17	    .normalize('NFD').replace(/[̀-ͯ]/g, '')
18	    .replace(/[^a-zA-Z0-9 ]/g, ' ')
19	    .trim()
20	    .substring(0, max) || '?';
21	
22	export const gerarPixPayload = ({ chave, nome, cidade, valor, txid }) => {
23	  const gui     = emv('00', 'br.gov.bcb.pix');
24	  const chaveId = emv('01', chave);
25	  const merch   = emv('26', gui + chaveId);
26	  const ref     = (txid ?? 'delivery').replace(/\W/g, '').substring(0, 25) || 'delivery';
